import axios from "axios";

const BASE_URL = "http://127.0.0.1:8000/api";
const LOGIN_URL = `${BASE_URL}/users/login/`;
const CARDS_URL = `${BASE_URL}/cards/`;
const REFRESH_TOKEN = `${BASE_URL}/users/refresh/`;

export const login = async (username, password) => {
  const response = await axios.post(
    LOGIN_URL,
    { username: username, password: password },
    { withCredentials: true }
  );
  return response.data.success;
};

export const refreshToken = () => {
  const response = axios.post(LOGIN_URL, {}, { withCredentials: true });

  return response.data.refreshed;
};

export const get_cards = async () => {
  {const response = await axios.get(CARDS_URL, { withCredentials: true });

  return response.data;}
};

const callRefresh = async (error, func) => {
  if (error.response && error.response.status === 401) {
    const tokenRefreshed = await refreshToken();

    if (tokenRefreshed) {
      const retryResponse = await func();

      return retryResponse.data;
    }
  }

  return false;
};
